<?php
namespace App\Controller;
use App\Entity\MapPlace; use Doctrine\ORM\EntityManagerInterface; use Symfony\Component\HttpFoundation\{JsonResponse,Request}; use Symfony\Component\HttpKernel\Exception\BadRequestHttpException; use Symfony\Component\Routing\Attribute\Route;
final readonly class MapSearchController { public function __construct(private EntityManagerInterface $em) {} #[Route('/api/map/search',name:'api_map_search',methods:['GET'])] #[Route('/api/objects/search',name:'api_objects_search',methods:['GET'],priority:200)] public function __invoke(Request $request): JsonResponse { $query=trim((string)$request->query->get('q')); if(mb_strlen($query)<2) throw new BadRequestHttpException('Поисковый запрос должен содержать минимум 2 символа.'); $qb=$this->em->getRepository(MapPlace::class)->createQueryBuilder('p')->andWhere('p.active = true')->andWhere('LOWER(p.name) LIKE LOWER(:q) OR p.searchAliases LIKE :q')->setParameter('q','%'.mb_strtolower($query).'%')->setMaxResults(30)->orderBy('p.priority','ASC'); if($plan=$request->query->getInt('plan')) $qb->andWhere('IDENTITY(p.plan) = :plan')->setParameter('plan',$plan); $items=array_map(static fn(MapPlace $p)=>['id'=>$p->getId(),'name'=>$p->name,'title'=>$p->name,'type'=>$p->type->value,'category'=>$p->category->value,'categoryLabel'=>$p->category->label(),'routeDrawn'=>$p->routeDrawn,'routeAvailable'=>$p->isRouteAvailable(),'mapId'=>$p->plan?->getId(),'floor'=>$p->plan?->getId(),'node'=>$p->node?->getId(),'area'=>$p->area?->getId(),'icon'=>$p->icon?->getUrl()],$qb->getQuery()->getResult()); return new JsonResponse(['items'=>$items,'total'=>count($items)]); } }
